from common import *
from itertools import product

lessons=[]
def add(*a,**kw):lessons.append(card(*a,**kw))

def sss(ab,bc,ac):
 x=(ab*ab+ac*ac-bc*bc)/(2*ab)
 return tri((0,0),(ab,0),(x,math.sqrt(max(0,ac*ac-x*x))))

def focus(m,label='Стороны и углы треугольника',segments=None,polygon=None,points=None):
 v={'label':label,'segments':segments or m['edges']}
 if polygon:v['polygon']=polygon
 if points:v['points']=points
 m['views']['focus']=v
 return m

def ordering(c,names):
 # Finite typography aliases. Every sequence retains the same mathematical order.
 aliases=[]
 possibilities=[[name,name[::-1]] if len(name)==2 else [name] for name in names]
 for seq in product(*possibilities):
  for sep in [';',',',', ',' ','']:
   value=sep.join(seq)
   for value in [value,value.lower(),value.translate(str.maketrans('ABC','АВС'))]:
    if value not in aliases:aliases.append(value)
 c['answer']['accepted']=aliases

